1	// pattern: Imperative Shell
2	//
3	//! Scheduled account-deletion reaper.
4	//!
5	//! `com.atproto.server.deactivateAccount` accepts an optional `deleteAfter` instant — a request to
6	//! permanently delete the account once that time passes. This periodic background task is what
7	//! finally acts on it: each pass lists every account whose `deleteAfter` has elapsed and permanently
8	//! deletes it via [`account_delete::purge_account`] (the same path as the interactive
9	//! `deleteAccount` endpoint — full local-data removal plus an `#account` deleted firehose frame).
10	//!
11	//! Resilient by design, like the blob and firehose GCs: an error deleting one account is logged and
12	//! counted but never aborts the pass, and the task runs for the life of the process (dropped on
13	//! shutdown rather than joined). `deleteAfter` is only ever set alongside `deactivated_at` and is
14	//! cleared on reactivation, so an account that reactivates before its window elapses is naturally
15	//! spared — its row no longer matches the "due" query.
16	
17	use std::time::Duration;
18	
19	use tokio::task::JoinHandle;
20	
21	use crate::account_delete::{purge_account, PurgeOutcome};
22	use crate::app::AppState;
23	use crate::db::accounts::accounts_due_for_deletion;
24	
25	/// Tally of what one reaper pass did, for logging and tests.
26	#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
27	pub struct ReaperStats {
28	    /// Accounts permanently deleted this pass.
29	    pub deleted: u64,
30	    /// Accounts that were due but skipped due to an error (logged, not fatal).
31	    pub errors: u64,
32	}
33	
34	/// Spawn the periodic scheduled-deletion reaper.
35	///
36	/// The first interval tick is consumed without running the reaper, so the server does not delete
37	/// accounts during startup; the first pass runs one `interval` after boot. The task loops for the
38	/// life of the process and is dropped on shutdown.
39	pub fn spawn_account_reaper(state: AppState, interval: Duration) -> JoinHandle<()> {
40	    tokio::spawn(async move {
41	        let mut ticker = tokio::time::interval(interval);
42	        // `interval`'s first tick fires immediately — skip it so the reaper doesn't run mid-boot.
43	        ticker.tick().await;
44	        loop {
45	            ticker.tick().await;
46	            run_account_reaper(&state).await;
47	        }
48	    })
49	}
50	
51	/// Run a single reaper pass: permanently delete every account whose `deleteAfter` has elapsed.
52	///
53	/// A no-op when nothing is due. An error listing the due accounts skips the whole pass (the next
54	/// pass retries); an error deleting a single account is logged and counted but lets the pass
55	/// continue with the rest.
56	pub async fn run_account_reaper(state: &AppState) -> ReaperStats {
57	    let mut stats = ReaperStats::default();
58	
59	    let due = match accounts_due_for_deletion(&state.db).await {
60	        Ok(dids) => dids,
61	        Err(e) => {
62	            tracing::error!(error = %e, "account reaper: failed to list due accounts; skipping pass");
63	            return stats;
64	        }
65	    };
66	
67	    for did in due {
68	        match purge_account(state, &did).await {
69	            Ok(PurgeOutcome::Deleted) => {
70	                stats.deleted += 1;
71	                tracing::info!(did = %did, "account reaper: permanently deleted scheduled account");
72	            }
73	            // Already gone (raced with an interactive deleteAccount): not an error.
74	            Ok(PurgeOutcome::NotFound) => {}
75	            Err(e) => {
76	                stats.errors += 1;
77	                tracing::warn!(did = %did, error = %e, "account reaper: failed to delete account; will retry next pass");
78	            }
79	        }
80	    }
81	
82	    if stats.deleted > 0 || stats.errors > 0 {
83	        tracing::info!(
84	            deleted = stats.deleted,
85	            errors = stats.errors,
86	            "account reaper pass complete"
87	        );
88	    }
89	
90	    // The failed-to-start early return above skips this on purpose: a stale
91	    // `account_reaper_last_run_timestamp` signals that passes are not completing.
92	    state.metrics.account_reaper_swept.add(stats.deleted, &[]);
93	    state
94	        .metrics
95	        .account_reaper_last_run_timestamp
96	        .record(crate::metrics::unix_now(), &[]);
97	    state
98	        .sweeps
99	        .record_account_reaper(crate::sweep_status::SweepRun::now(stats.deleted));
100	
101	    stats
102	}
