140	        // The pass's instruments fire: the deletion is counted and the pass is timestamped.
141	        let rendered = state.metrics.render().unwrap().unwrap();
142	        assert!(
143	            rendered.contains("account_reaper_swept_total"),
144	            "missing account_reaper_swept_total in:\n{rendered}"
