156	    #[tokio::test]
157	    async fn reaps_account_due_earlier_today() {
158	        // Boundary case: a `delete_after` earlier *today*, stored in RFC 3339 (with the `T`
159	        // separator and a `Z`), must be reaped. A raw text comparison against `datetime('now')`
160	        // (`YYYY-MM-DD HH:MM:SS`) would wrongly keep it, since `'T'` sorts after `' '`; the query
161	        // normalises both sides through `datetime()` to avoid exactly that.
162	        let state = test_state().await;
163	        let one_minute_ago = (chrono::Utc::now() - chrono::Duration::minutes(1))
164	            .to_rfc3339_opts(chrono::SecondsFormat::Secs, true);
165	        insert_deactivated(&state.db, "did:plc:reaptoday", &one_minute_ago).await;
166	
167	        let stats = run_account_reaper(&state).await;
168	        assert_eq!(stats.deleted, 1, "an instant earlier today is due");
169	        assert!(!account_exists(&state.db, "did:plc:reaptoday").await);
170	    }
