6	// ── Old-model re-key migration (MM-411) ───────────────────────────────────────
7	//
8	// Moves a pre-existing account off the voided server-generated split and onto the
9	// client-generated recovery model: generate a new seed, insert its recovery key at
10	// rotationKeys[1] via a device-key-signed PLC op (device stays [0], PDS shifts to [2]),
11	// escrow the new Share 2, rewrite the local Share 1, and walk the user through saving the
12	// new Share 3. Additive and resumable — see `rekey.rs`.
13	
14	/**
15	 * Error returned by the re-key flow. Matches `RekeyError` in `rekey.rs`
16	 * (`#[serde(tag = "code", rename_all = "SCREAMING_SNAKE_CASE", rename_all_fields = "camelCase")]`) —
17	 * codes must match exactly.
18	 *
19	 * `SESSION_LOCKED` is the cue to run the passwordless {@link sovereignLogin} (biometric) and
20	 * retry, exactly as in the rotation/migration flows.
21	 */
22	export type RekeyError =
23	  // The DID is a did:web identity — the recovery-key model does not apply.
24	  | { code: 'NOT_DID_PLC' }
25	  // The identity already carries a recovery key (new-model) — nothing to re-key.
26	  | { code: 'ALREADY_REKEYED' }
27	  // The wallet's device key is not rotationKeys[0], so it cannot additively re-key.
28	  | { code: 'WALLET_NOT_AUTHORIZED' }
29	  // The identity is locked — run sovereignLogin(did) and retry.
30	  | { code: 'SESSION_LOCKED'; reason: UnlockReason }
31	  | { code: 'RATE_LIMITED'; retryAfter: string | null }
32	  // The strict additive pre-sign guard rejected the op.
33	  | { code: 'GUARD_REJECTED'; reason: string }
34	  | { code: 'INVALID_AUDIT_LOG'; message: string }
35	  | { code: 'SHARE_GENERATION_FAILED'; message: string }
36	  | { code: 'SIGNING_FAILED'; message: string }
37	  | { code: 'PLC_SUBMISSION_FAILED'; message: string }
38	  | { code: 'ESCROW_FAILED'; status: number; message: string }
39	  | { code: 'SHARE_STORAGE_FAILED'; message: string }
40	  // Confirm was called before Share 1 reached its durable slot.
41	  | { code: 'SHARE_NOT_STORED' }
42	  | { code: 'NETWORK_ERROR'; message: string }
43	  | { code: 'IDENTITY_NOT_FOUND'; message: string };
44	
45	/**
46	 * Preview of a re-key, driving the review screen. Matches `RekeyPreview` in `rekey.rs`
47	 * (`#[serde(rename_all = "camelCase")]`).
48	 */
49	export interface RekeyPreview {
50	  /** The additive key diff — `addedKeys: [recovery]`, `removedKeys: []` (nothing is lost). */
51	  diff: OpDiff;
52	  /** The recovery `did:key` that will be inserted at rotationKeys[1]. */
53	  recoveryKeyId: string;
54	}
55	
56	/**
57	 * Result of a completed re-key. Matches `RekeyResult` in `rekey.rs`
58	 * (`#[serde(rename_all = "camelCase")]`).
59	 */
60	export interface RekeyResult {
61	  /** The refreshed DID document (PLC data shape) so the home card updates immediately. */
62	  updatedDidDoc: Record<string, unknown>;
63	  /** The new Share 3 envelope (base32/QR form) for the user to save. */
64	  share3: string;
65	  /** The new Share 3 rendered as the BIP-39-style word phrase. */
66	  share3Words: string;
67	}
68	
69	/**
70	 * Build the re-key preview: generate + stage the new recovery share set, prove the account is
71	 * an eligible old-model did:plc identity, and return the additive diff for review.
72	 *
73	 * Idempotent — the staged set is reused across retries. Signs nothing (submit does that).
74	 * Rejects with `SESSION_LOCKED` only downstream in {@link submitRekey}; build touches only the
75	 * public audit log.
76	 */
77	export const buildRekey = (did: string): Promise<RekeyPreview> => invoke('build_rekey_cmd', { did });
78	
79	/**
80	 * Run the re-key: post the additive rotation op (device-key-signed) to plc.directory, escrow
81	 * the new Share 2, overwrite the durable Share 1, and refresh the cache. Returns the new Share 3.
82	 *
83	 * The biometric prompt precedes the IPC invocation (the owner gate on an identity operation);
84	 * cancellation never reaches the network. Idempotent/resumable: a lost response or interrupted
85	 * run is healed by calling this again — every step converges on the same terminal state, and no
86	 * intermediate state drops recovery capability below the pre-re-key baseline.
87	 *
88	 * On `SESSION_LOCKED`, run {@link sovereignLogin} and retry.
89	 */
90	export const submitRekey = async (did: string): Promise<RekeyResult> => {
91	  await authenticateBiometric('Confirm your recovery-key upgrade');
92	  return invoke('submit_rekey_cmd', { did });
93	};
94	
95	/**
96	 * Confirm the user has saved the new Share 3 and tear down the staging slot. Idempotent; called
97	 * when the Shamir backup screen's confirmation completes. Rejects with `SHARE_NOT_STORED` if
98	 * Share 1 is not durably present (the staging record must survive until then).
99	 */
100	export const confirmRekey = (did: string): Promise<void> => invoke('confirm_rekey_cmd', { did });
101	
102	/**
103	 * Whether a re-key is mid-flight for this DID (a per-DID staging slot exists). The home surface
104	 * treats this as "prompt the upgrade" even when the identity already reads as new-model — it
105	 * resurfaces an interrupted re-key whose PLC op landed but whose escrow/Share 1 did not finish.
106	 */
107	export const rekeyInProgress = (did: string): Promise<boolean> =>
108	  invoke('rekey_in_progress_cmd', { did });
