67	  /** Run `fn` with the session pre-flight: unlock passwordlessly once if locked. */
68	  async function withUnlockedSession<T>(fn: () => Promise<T>): Promise<T> {
69	    try {
70	      await ensureIdentitySession(did);
71	    } catch (e) {
72	      if (isCodedError(e) && e.code === 'NEEDS_UNLOCK') {
73	        await sovereignLogin(did);
74	      } else {
75	        throw e;
76	      }
77	    }
78	    try {
79	      return await fn();
80	    } catch (e) {
81	      if (isCodedError(e) && e.code === 'SESSION_LOCKED') {
82	        await sovereignLogin(did);
83	        return await fn();
84	      }
85	      throw e;
86	    }
87	  }
