340	async fn deposit_escrow_share(
341	    session: &crate::oauth_client::OAuthClient,
342	    share2: &str,
343	) -> Result<(), RekeyError> {
344	    let response = session
345	        .put(
346	            "/v1/recovery/escrow-share",
347	            &serde_json::json!({ "share": share2 }),
348	        )
349	        .await
350	        .map_err(|e| RekeyError::NetworkError {
351	            message: format!("escrow deposit request failed: {e}"),
352	        })?;
353	    if response.status().is_success() {
354	        return Ok(());
355	    }
356	    let status = response.status().as_u16();
357	    if status == 429 {
358	        let retry_after = response
359	            .headers()
360	            .get(reqwest::header::RETRY_AFTER)
361	            .and_then(|v| v.to_str().ok())
362	            .map(str::to_string);
363	        return Err(RekeyError::RateLimited { retry_after });
364	    }
365	    let body = response.text().await.unwrap_or_default();
366	    let message = serde_json::from_str::<serde_json::Value>(&body)
367	        .ok()
368	        .and_then(|v| v.get("message").and_then(|m| m.as_str()).map(String::from))
369	        .unwrap_or_else(|| {
370	            if body.is_empty() {
371	                format!("escrow deposit returned HTTP {status}")
372	            } else {
373	                body
374	            }
375	        });
376	    Err(RekeyError::EscrowFailed { status, message })
377	}
