379	/// Overwrite the per-DID Share 1 Keychain slot with `share1`, verifying the write by reading it
380	/// back — Share 1's durability is the precondition for tearing down the staging slot later.
381	fn store_and_verify_share1(did: &str, share1: &str) -> Result<(), RekeyError> {
382	    let account = recovery_share1_account(did);
383	    crate::keychain::store_item(&account, share1.as_bytes()).map_err(|e| {
384	        RekeyError::ShareStorageFailed {
385	            message: format!("keychain write failed: {e}"),
386	        }
387	    })?;
388	    match crate::keychain::get_item(&account) {
389	        Ok(read_back) if read_back == share1.as_bytes() => Ok(()),
390	        Ok(_) => Err(RekeyError::ShareStorageFailed {
391	            message: "recovery share 1 read-back does not match the written value".to_string(),
392	        }),
393	        Err(e) => Err(RekeyError::ShareStorageFailed {
394	            message: format!("recovery share 1 read-back failed: {e}"),
395	        }),
396	    }
397	}
