399	// ── Imperative shell: build / submit / confirm ───────────────────────────────
400	
401	/// Build the re-key preview: generate + stage the new recovery share set, fetch current state,
402	/// prove the account is an eligible old-model did:plc identity, and return the additive diff.
403	///
404	/// Idempotent — the staged set is reused across retries (same recovery key, same `set_id`), so
405	/// re-running build never orphans a prior attempt's material. Signs nothing; `submit_rekey`
406	/// does the single device-key signature.
407	pub async fn build_rekey(pds_client: &PdsClient, did: &str) -> Result<RekeyPreview, RekeyError> {
408	    require_did_plc(did)?;
409	    let store = IdentityStore;
410	
411	    let device = store
412	        .get_or_create_device_key(did)
413	        .map_err(|e| RekeyError::IdentityNotFound {
414	            message: format!("failed to get device key: {e}"),
415	        })?;
416	
417	    let current = fetch_current_state(pds_client, did).await?;
418	    let pds_url = pds_endpoint(&current);
419	
420	    // Eligibility precheck BEFORE generating/staging anything: a fresh re-key requires the 2-key
421	    // old model, but a re-key already in flight (a staging slot exists) is always resumable — even
422	    // after its PLC op landed and the identity reads as new-model — because escrow/Share 1 may
423	    // still be unfinished. A new-model identity with no in-flight re-key has nothing to do.
424	    let staging_exists = crate::share_ceremony::rekey_staging_exists(did);
425	    if !staging_exists && current.rotation_keys.len() != 2 {
426	        return Err(RekeyError::AlreadyRekeyed);
427	    }
428	
429	    let shares = crate::share_ceremony::load_or_create_for_rekey(did, &pds_url).map_err(|e| {
430	        RekeyError::ShareGenerationFailed {
431	            message: e.to_string(),
432	        }
433	    })?;
434	
435	    // Only run the strict additive guard when the recovery key is not yet on-chain — i.e. this
436	    // build will additively insert it. On a resumed re-key whose op already landed, the recovery
437	    // key is present and the guard's "current is exactly [device, PDS]" precondition no longer
438	    // holds; the remaining work (escrow/Share 1) is finished by `submit_rekey`.
439	    if !current.rotation_keys.contains(&shares.recovery_key_id) {
440	        let proposed_rotation_keys =
441	            proposed_rekey_keys(&current.rotation_keys, &shares.recovery_key_id);
442	        let inputs = RekeyInputs {
443	            device_key_id: device.key_id.clone(),
444	            recovery_key_id: shares.recovery_key_id.clone(),
445	            current_rotation_keys: current.rotation_keys.clone(),
